// Create lookup maps
const GI_ITEM_NAMES: Map<string, string> = new Map(
  GI_ITEM_LIST.map((item) => [item.id, item.name]),
);
const ITEM_DB_NAMES: Map<string, string> = new Map(
  ITEM_DATABASE.map((item) => [item.id, item.name]),
);

/**
 * Get the display name for an item ID.
 * Falls back to a formatted version of the ID if not found.
 */
export function getItemName(itemId: string): string {
  // Check GI_ITEM_LIST first (from giItems.ts)
  const giName = GI_ITEM_NAMES.get(itemId);
  if (giName) {
    return giName;
  }

  // Check ITEM_DATABASE
  const dbName = ITEM_DB_NAMES.get(itemId);
  if (dbName) {
    return dbName;
  }

  // Fallback: format the ID as a readable name
  let name = itemId.replace(
    /^(OOT_|MM_|SHARED_|EVENT_OOT_|EVENT_MM_|EVENT_)/,
    '',
  );
  return name
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
}
